 57	/**
 58	 * Reading and writing personas — what they are is the schema file's
 59	 * story (`schema/personas.ts`); this file is how they are reached.
 60	 *
 61	 * The first project-scoped entity, so the first table where `within` narrows
 62	 * by the project as well as the organization. A context acting in a project
 63	 * writes and reads there; a context acting in none — an organization-scoped
 64	 * credential — reads the whole customer and creates nothing, because a
 65	 * persona belongs to a project and a credential for the whole customer
 66	 * is acting in none. What already exists it may edit: the row names its own
 67	 * project, so that write has somewhere to land. Archiving it refuses like
 68	 * creating, because taking a persona out of a project's authoring lists is an
 69	 * act taken inside one — `archivePersona` says why.
 70	 *
 71	 * **Nothing here deletes anybody.** Archive and Restore are the whole
 72	 * lifecycle: a persona a run pinned has to stay interpretable forever, and a
 73	 * removal somebody regrets at four o'clock has to be undoable at five.
 74	 * Permanent removal is a compliance workflow with its own rules and is not
 75	 * one of these verbs.
 76	 */
 77	
 78	export type { PersonaTraits };
 79	
 80	/** Human traits that can be described but are not required. */
 81	const DESCRIBED_TRAITS = [
 82	  "manner",
 83	  "patience",
 84	  "accent",
 85	  "backgroundNoise",
 86	  "underFriction",
 87	] as const;
 88	
 89	type DescribedTrait = (typeof DESCRIBED_TRAITS)[number];
 90	
 91	/**
 92	 * The traits as they are stored and compared: described fields trimmed, and
 93	 * an empty one dropped rather than kept as an empty string.
 94	 *
 95	 * **This is what makes a byte-identical save byte-identical.** A field
 96	 * somebody cleared and a field somebody never filled in are the same fact —
 97	 * nothing is stated about it — and storing them as two different values would
 98	 * mint a version for a change nobody made.
 99	 */
100	function normalizedTraits(traits: PersonaTraits): PersonaTraits {
101	  const described: { [K in DescribedTrait]?: string } = {};
102	  for (const field of DESCRIBED_TRAITS) {
103	    const written = traits[field]?.trim() ?? "";
104	    if (written !== "") described[field] = written;
105	  }
106	  return {
107	    personality: traits.personality.trim(),
108	    language: traits.language.trim(),
109	    ...described,
110	  };
111	}
112	
113	export type NewPersona = {
114	  readonly name: string;
115	  readonly description?: string | undefined;
116	  readonly traits: PersonaTraits;
117	  /** Absent means the release's complete recommended selection. */
118	  readonly models?: PersonaModels | undefined;
119	};
