121	export type PersonaOwner = "egma" | "organization";
122	
123	export type Persona = {
124	  readonly id: string;
125	  readonly owner: PersonaOwner;
126	  readonly projectId: string | null;
127	  readonly name: string;
128	  readonly description: string | null;
129	  readonly version: number;
130	  /** The current version's own `prsv_` id — what a run pins. */
131	  readonly versionId: string;
132	  readonly traits: PersonaTraits;
133	  readonly models: PersonaModels;
134	  /**
135	   * The opaque token an identity write or a lifecycle change has to name.
136	   * It changes on every one of them and means nothing on its own.
137	   */
138	  readonly revision: string;
139	  /** When they were archived, or null while they are active. */
140	  readonly archivedAt: Date | null;
141	  /**
142	   * Whether the project points at them as the persona a test naming nobody
143	   * gets. **A pointer, not a kind**: it may point at a read-only Egma-provided
144	   * persona or at a Custom persona.
145	   */
146	  readonly isDefault: boolean;
147	  readonly createdAt: Date;
148	  readonly updatedAt: Date;
149	};
150	
151	/**
152	 * What an edit may touch. Name and description are identity and version
153	 * nothing; traits are human behavior and version on a change. Absent means
154	 * keep.
155	 *
156	 * **The two expectations are separate because they answer separate
157	 * questions.** `expectedRevision` says *this persona has not moved* and guards
158	 * the identity fields and the lifecycle; `expectedVersionId` says *this
159	 * human behavior has not moved* and guards the authored behavior. An edit that
160	 * changes both names both. Either may be left out, and then that half is
161	 * written without a check — which is what the scripts do, and what no browser
162	 * write is ever allowed to do.
163	 */
164	export type PersonaChanges = {
165	  readonly name?: string;
166	  readonly description?: string | null;
167	  readonly traits?: PersonaTraits;
168	  readonly models?: PersonaModels;
169	  readonly expectedRevision?: string | undefined;
170	  readonly expectedVersionId?: string | undefined;
171	};
172	
173	/** One version, frozen: the persona exactly as some simulation met them. */
174	export type PersonaVersion = {
175	  readonly id: string;
176	  readonly personaId: string;
177	  readonly version: number;
178	  readonly traits: PersonaTraits;
179	  readonly models: PersonaModels;
180	  readonly createdAt: Date;
181	};
