183	const notArchived: SQL = isNull(persona.archivedAt);
184	
185	/** An answer's columns, and no more — the hash-free, tenant-free view. */
186	const COLUMNS = {
187	  id: persona.id,
188	  organizationId: persona.organizationId,
189	  projectId: persona.projectId,
190	  name: persona.name,
191	  description: persona.description,
192	  revision: persona.revision,
193	  archivedAt: persona.archivedAt,
194	  createdAt: persona.createdAt,
195	  updatedAt: persona.updatedAt,
196	} as const;
197	
198	/**
199	 * What the factory will not write, refused as the caller's mistake rather than
200	 * as a fault.
201	 *
202	 * `UnprocessableInputError` rather than a plain `Error` because these
203	 * sentences are written for whoever has to fix the input, and a layer above
204	 * has to be able to tell them apart from something being broken. They were
205	 * plain errors while nothing but a script called this; the browser's door is
206	 * the caller that has to relay them.
207	 */
208	function validateName(name: unknown): asserts name is string {
209	  if (typeof name !== "string" || name.trim() === "") {
210	    throw new UnprocessableInputError("a persona needs a name");
211	  }
212	}
213	
214	function validateTraits(traits: unknown): asserts traits is PersonaTraits {
215	  if (typeof traits !== "object" || traits === null || Array.isArray(traits)) {
216	    throw new UnprocessableInputError("persona traits must be an object");
217	  }
218	  const held = traits as Record<string, unknown>;
219	  if (
220	    typeof held.personality !== "string" ||
221	    held.personality.trim() === ""
222	  ) {
223	    throw new UnprocessableInputError("a persona needs a personality");
224	  }
225	  if (typeof held.language !== "string" || held.language.trim() === "") {
226	    throw new UnprocessableInputError("a persona needs a language");
227	  }
228	  const accepted = new Set<string>([
229	    "personality",
230	    "language",
231	    ...DESCRIBED_TRAITS,
232	  ]);
233	  const unsupported = Object.keys(held).filter((key) => !accepted.has(key));
234	  if (unsupported.length > 0) {
235	    throw new UnprocessableInputError(
236	      `persona traits have unsupported fields ${unsupported.join(", ")}`,
237	    );
238	  }
239	  for (const field of DESCRIBED_TRAITS) {
240	    const value = held[field];
241	    if (value !== undefined && typeof value !== "string") {
242	      throw new UnprocessableInputError(`persona trait ${field} must be text`);
243	    }
244	  }
245	}
246	
247	const CREATE_FIELDS = ["name", "description", "traits", "models"] as const;
248	const EDIT_FIELDS = [
249	  "name",
250	  "description",
251	  "traits",
252	  "models",
253	  "expectedRevision",
254	  "expectedVersionId",
255	] as const;
256	
257	/**
258	 * Reject stale or misspelled authoring fields before reading a required one.
259	 *
260	 * TypeScript keeps current in-repo callers honest, but this boundary is also
261	 * called by built JavaScript and can receive an object written against an
262	 * older release. Ignoring an old `traits` field on edit would report success
263	 * while changing nothing; reading its absent replacement on create would
264	 * throw a TypeError. Both are caller mistakes, so both get one stable input
265	 * refusal that names the accepted fields.
266	 */
267	function validateAuthoringFields(
268	  operation: "create" | "edit",
269	  input: unknown,
270	  accepted: readonly string[],
271	): void {
272	  if (typeof input !== "object" || input === null || Array.isArray(input)) {
273	    throw new UnprocessableInputError(
274	      `persona ${operation} input must be an object`,
275	    );
276	  }
277	  const acceptedSet = new Set(accepted);
278	  const unsupported = Object.getOwnPropertyNames(input)
279	    .filter((field) => !acceptedSet.has(field))
280	    .sort();
281	  if (unsupported.length === 0) return;
282	
283	  const quoted = (fields: readonly string[]) =>
284	    fields.map((field) => `"${field}"`).join(", ");
285	  throw new UnprocessableInputError(
286	    `persona ${operation} received unsupported fields ${quoted(unsupported)}; accepted fields are ${quoted(accepted)}`,
287	  );
288	}
289	
290	function validateNewPersona(input: NewPersona): void {
291	  validateAuthoringFields("create", input, CREATE_FIELDS);
292	  validateName(input.name);
293	  validateTraits(input.traits);
294	  if (input.models !== undefined) validPersonaModels(input.models);
295	}
296	
297	function describedTraitsFromRow(
298	  value: Record<string, unknown>,
299	  malformed: () => Error,
300	): { [K in DescribedTrait]?: string } {
301	  const described: { [K in DescribedTrait]?: string } = {};
302	  for (const field of DESCRIBED_TRAITS) {
303	    const held = value[field];
304	    if (held === undefined) continue;
305	    if (typeof held !== "string" || held.trim() === "") throw malformed();
306	    described[field] = held;
307	  }
308	  return described;
309	}
310	
311	/**
312	 * The shape guard on every read. Stored jsonb comes back `unknown`, and a row
313	 * somebody hand-edited must fail here, loudly and naming itself, rather than
314	 * leak into a caller as a `PersonaTraits` that isn't one. This guard accepts
315	 * only human behavior fields. Provider, model, voice, and speed are validated
316	 * separately as the version's required `models` value.
317	 */
318	function traitsFromRow(value: unknown, versionId: string): PersonaTraits {
319	  const malformed = () =>
320	    new Error(
321	      `version ${versionId} holds traits in a shape Egma never writes; the row needs repairing before anybody can read it`,
322	    );
323	
324	  if (typeof value !== "object" || value === null || Array.isArray(value)) {
325	    throw malformed();
326	  }
327	  const held = value as Record<string, unknown>;
328	  const { personality, language } = held;
329	  if (typeof personality !== "string" || personality.trim() === "") {
330	    throw malformed();
331	  }
332	  if (typeof language !== "string" || language.trim() === "") throw malformed();
333	  const accepted = new Set<string>([
334	    "personality",
335	    "language",
336	    ...DESCRIBED_TRAITS,
337	  ]);
338	  if (Object.keys(held).some((key) => !accepted.has(key))) throw malformed();
339	  return {
340	    personality,
341	    language,
342	    ...describedTraitsFromRow(held, malformed),
343	  };
344	}
345	
346	/**
347	 * Byte-identical or not, decided field by field — the same answer canonical
348	 * serialization would give, without trusting any serializer to order keys the
349	 * way jsonb re-ordered them.
350	 *
351	 * One comparator per field, in tables the compiler holds exhaustive: a field
352	 * added to the human traits refuses to build until it is also told how to
353	 * compare. A hand-maintained comparator that missed a field would call two
354	 * different traits identical, and an edit would vanish without a version —
355	 * the one loss this whole file exists to rule out.
356	 */
357	const sameTraitsField: {
358	  readonly [K in keyof PersonaTraits]-?: (
359	    a: PersonaTraits,
360	    b: PersonaTraits,
361	  ) => boolean;
362	} = {
363	  personality: (a, b) => a.personality === b.personality,
364	  language: (a, b) => a.language === b.language,
365	  manner: (a, b) => a.manner === b.manner,
366	  patience: (a, b) => a.patience === b.patience,
367	  accent: (a, b) => a.accent === b.accent,
368	  backgroundNoise: (a, b) => a.backgroundNoise === b.backgroundNoise,
369	  underFriction: (a, b) => a.underFriction === b.underFriction,
370	};
371	
372	/**
373	 * Byte-identical, decided over the **normalized** traits on both sides. The
374	 * stored side came out of `traitsFromRow`, which drops an empty described
375	 * trait; the incoming side has to be put through the same door or a cleared
376	 * field would compare unequal to an absent one forever.
377	 */
378	function sameTraits(a: PersonaTraits, b: PersonaTraits): boolean {
379	  const left = normalizedTraits(a);
380	  const right = normalizedTraits(b);
381	  return Object.values(sameTraitsField).every((same) => same(left, right));
382	}
383	
384	/**
385	 * Full JSON equality for a fixed catalog version. Unlike `sameTraits`, this
386	 * must not parse through today's trait shape: doing so would drop an unknown
387	 * key and let a corrupted immutable row pass as catalog content. Object key
388	 * order is not content; every key and nested value is.
389	 */
390	function sameJson(left: unknown, right: unknown): boolean {
391	  if (Object.is(left, right)) return true;
392	  if (Array.isArray(left) || Array.isArray(right)) {
393	    return (
394	      Array.isArray(left) &&
395	      Array.isArray(right) &&
396	      left.length === right.length &&
397	      left.every((value, index) => sameJson(value, right[index]))
398	    );
399	  }
400	  if (
401	    typeof left !== "object" ||
402	    left === null ||
403	    typeof right !== "object" ||
404	    right === null
405	  ) {
406	    return false;
407	  }
408	
409	  const leftRecord = left as Record<string, unknown>;
410	  const rightRecord = right as Record<string, unknown>;
411	  const leftKeys = Object.keys(leftRecord);
412	  const rightKeys = Object.keys(rightRecord);
413	  return (
414	    leftKeys.length === rightKeys.length &&
415	    leftKeys.every(
416	      (key) =>
417	        Object.hasOwn(rightRecord, key) &&
418	        sameJson(leftRecord[key], rightRecord[key]),
419	    )
420	  );
421	}
422	
423	/**
424	 * The named persona, within the caller's tenancy and scope, **whatever their
425	 * lifecycle state**.
426	 *
427	 * Archive takes somebody out of the lists an author picks from; it does not
428	 * take them out of the product. A detail page has to render an archived
429	 * persona — that is where Restore is — and Restore itself has to find one. A
430	 * predicate that filtered them out here would make an archived persona
431	 * unreachable by the one operation that exists to bring them back.
432	 */
433	function thePersona(auth: AuthContext, id: string): SQL {
434	  return readablePersona(auth, eq(persona.id, id));
435	}
436	
437	export type SeededPersona = {
438	  readonly id: string;
439	  readonly name: string;
440	  readonly version: number;
200	    models: one.models,
201	    owner: one.owner,
202	    // The two expectations a write can name, always answered, so that reading
203	    // a persona is always enough to edit one.
204	    revision: one.revision,
205	    archivedAt: one.archivedAt?.toISOString() ?? null,
206	    isDefault: one.isDefault,
207	    createdAt: one.createdAt.toISOString(),
208	    updatedAt: one.updatedAt.toISOString(),
209	  };
210	}
211	
212	/** One frozen version of one, as history and the older-version read show it. */
213	function describedVersion(one: PersonaVersion): Record<string, unknown> {
214	  return {
215	    id: one.id,
216	    personaId: one.personaId,
217	    version: one.version,
218	    traits: one.traits,
219	    models: one.models,
220	    createdAt: one.createdAt.toISOString(),
221	  };
222	}
223	
224	/**
225	 * The human behavior a body carries, as the factory takes it.
226	 *
227	 * Model selection is the adjacent `models` value. Technical voice exists only
228	 * at `models.tts`. Refusing any other trait is important: silently dropping
229	 * one would say a control worked when no simulator behavior exists for it.
230	 */
231	type WrittenTraits =
232	  | { readonly traits: PersonaTraits }
233	  | { readonly refusal: string };
234	
235	const HUMAN_TRAIT_FIELDS = [
236	  "personality",
237	  "language",
238	  "manner",
239	  "patience",
240	  "accent",
241	  "backgroundNoise",
242	  "underFriction",
243	] as const;
244	
245	function traitsIn(value: unknown): WrittenTraits {
246	  if (typeof value !== "object" || value === null || Array.isArray(value)) {
247	    return {
248	      refusal:
249	        "traits describe who the persona is. Send them as an object with a " +
250	        "personality and language.",
251	    };
252	  }
253	  const held = value as Body;
254	  const supported = new Set<string>(HUMAN_TRAIT_FIELDS);
255	  const unsupported = Object.keys(held).filter((field) => !supported.has(field));
256	  if (unsupported.length > 0) {
257	    return {
258	      refusal:
259	        `persona traits have unsupported fields ${unsupported.join(", ")}. ` +
260	        "Provider, model, voice id, and speed belong in models.",
261	    };
262	  }
263	
264	  const optional = Object.fromEntries(
265	    HUMAN_TRAIT_FIELDS.slice(2).flatMap((field) =>
266	      Object.hasOwn(held, field) ? [[field, text(held[field])]] : [],
267	    ),
268	  );
269	  return {
270	    traits: {
271	      personality: text(held.personality),
272	      language: text(held.language),
273	      ...optional,
274	    },
275	  } as WrittenTraits;
276	}
277	
278	/* ------------------------------------------------------------ the project */
279	
280	/**
281	 * Which project this request is about.
282	 *
283	 * **A browser names it every time.** The project a tab is looking at lives in
284	 * that tab's address and nowhere else, so a session that named none is a
285	 * request egma cannot answer — and answering it about *some* project would be
286	 * the silent narrowing this codebase has already had to find once. An API key
287	 * is different: one minted for a project already names it, and
288	 * `actingIn` resolves that without the caller repeating it.
289	 */
290	async function projectFor(
291	  auth: AuthContext,
292	  named: string | undefined,
293	): Promise<Acting> {
294	  if (auth.via === "session" && named === undefined) {
295	    return { refusal: REFUSALS.projectRequired(), code: "project_required" };
296	  }
297	  return actingIn(auth, named);
298	}
299	
300	/* -------------------------------------------------------------- the routes */
301	
302	export async function personaRoutes(
303	  app: FastifyInstance,
304	  options: PersonaRoutesOptions,
305	): Promise<void> {
306	  credentialed(app, {
307	    provider: options.provider,
308	    rateLimit: options.rateLimit,
309	  });
310	
