 33	import { personaOperations } from "@egma/platform-api/contract";
 34	import type { FastifyInstance, FastifyReply } from "fastify";
 35	
 36	import type { SessionIdentityProvider } from "../auth/seam.ts";
 37	import { actingIn, refuseActing, type Acting } from "../http/acting.ts";
 38	import { credentialed, requesterOf } from "../http/credentialed.ts";
 39	import type { RateLimit } from "../http/rate-limit.ts";
 40	import { given, text } from "../http/reading.ts";
 41	import { registerPlatformOperation } from "../http/platform-operation.ts";
 42	import { identityConflict, sendRefusal } from "../http/refusals.ts";
 43	
 44	/**
 45	 * The personas available to one project: the shared definitions Egma ships,
 46	 * the Custom definitions a team authors, their history and their uses.
 47	 *
 48	 * A **persona** is the synthetic person who speaks with the agent. Name and
 49	 * Description identify them. Personality is human behavior. Models are the
 50	 * complete technical selection used to bring that behavior to life.
 51	 *
 52	 * Three shapes here are contract rather than convenience.
 53	 *
 54	 * **Identity is live and content is versioned, and the wire says which is
 55	 * which.** Name, description and archive state are written in place. Traits
 56	 * mint an immutable version, and traits byte-identical to the current version
 57	 * mint nothing. So a write names *two* expectations where it touches both:
 58	 * `expectedRevision` for the identity and `expectedVersionId` for the
 59	 * content, refused separately because they are separately recoverable.
 60	 *
 61	 * **A Custom persona is never deleted.** Archive takes them out of the
 62	 * authoring list and leaves every version in place. Egma-provided personas
 63	 * have no project lifecycle and cannot be changed; Fork is how a team gets a
 64	 * Custom version of one.
 65	 *
 66	 * **Names are not unique, so nothing here is addressed by one.** Every address
 67	 * and every reference is a stable `prs_` identifier. Two personas called
 68	 * "Impatient caller" is an ordinary thing for a project to hold, and a surface
 69	 * that resolved a name would have to pick one of them.
 70	 */
 71	
 72	export type PersonaRoutesOptions = {
 73	  readonly provider: SessionIdentityProvider;
 74	  readonly rateLimit: RateLimit;
 75	};
 76	
 77	type Body = Record<string, unknown>;
 78	
 79	type Query = {
 80	  readonly projectId?: string;
