 96	 * somebody cleared and a field somebody never filled in are the same fact —
 97	 * nothing is stated about it — and storing them as two different values would
 98	 * mint a version for a change nobody made.
 99	 */
100	function normalizedTraits(traits: PersonaTraits): PersonaTraits {
101	  const described: { [K in DescribedTrait]?: string } = {};
102	  for (const field of DESCRIBED_TRAITS) {
103	    const written = traits[field]?.trim() ?? "";
104	    if (written !== "") described[field] = written;
105	  }
106	  return {
107	    personality: traits.personality.trim(),
108	    language: traits.language.trim(),
109	    ...described,
