102	/**
103	 * What a write actually put in its body, and the values it put there.
104	 *
105	 * A field is present here only if the request carried it. That is the whole
106	 * distinction the adoption below turns on, so it is a shape rather than a
107	 * convention: a save that forgets to declare a field it sent cannot silently
108	 * get that field adopted, and a save that declares one it did not send cannot
109	 * exist.
110	 */
111	type Submitted = {
112	  readonly personaId: string;
113	  readonly name?: string;
114	  readonly description?: string;
115	  readonly traits?: TraitsDraft;
116	  readonly models?: ModelsDraft;
117	};
