160	/** One complete models value, in the exact shape the API validates. */
161	export function modelsFrom(draft: ModelsDraft): PersonaModels {
162	  const speed = Number(draft.speed);
163	  const models = {
164	    llm: { provider: draft.llmProvider, model: draft.llmModel },
165	    stt: { provider: draft.sttProvider, model: draft.sttModel },
166	    tts: {
