 82	 * before it was: name and description are *live* — rewriting them changes
 83	 * nothing about any simulation that ever ran — and personality and models are
 84	 * *versioned*, because a run pinned the exact pair it used. So a save of the
 85	 * first is a save, a save of the second mints a version, and the note at the
 86	 * end of `MODELS` says so before anybody presses anything.
 87	 *
 88	 * An Egma-provided persona (`CDO-0`) has no editor at all and offers Fork; an
 89	 * archived one (`CM9-0`) offers Restore. Both are read views with a different
 90	 * footer, because both are the same facts.
 91	 */
 92	
 93	/** What the editor in this sheet is holding, between reads and writes. */
 94	type Draft = {
 95	  readonly personaId: string;
 96	  readonly name: string;
 97	  readonly description: string;
 98	  readonly traits: TraitsDraft;
 99	  readonly models: ModelsDraft;
100	};
101	
102	/**
103	 * What a write actually put in its body, and the values it put there.
104	 *
105	 * A field is present here only if the request carried it. That is the whole
106	 * distinction the adoption below turns on, so it is a shape rather than a
107	 * convention: a save that forgets to declare a field it sent cannot silently
108	 * get that field adopted, and a save that declares one it did not send cannot
109	 * exist.
110	 */
111	type Submitted = {
112	  readonly personaId: string;
113	  readonly name?: string;
114	  readonly description?: string;
115	  readonly traits?: TraitsDraft;
116	  readonly models?: ModelsDraft;
117	};
118	
119	/**
120	 * The server's answer, taken into the draft.
121	 *
122	 * **The invariant, stated once: adoption may touch exactly the fields the
123	 * request carried, and among those, only where the draft still holds what was
124	 * sent.** Everything outside the submitted set is left alone, always.
125	 *
126	 * Both halves are load-bearing and each was learned the hard way.
127	 *
128	 * - *Only the submitted fields.* One save sends only fields that changed. A
129	 *   reply carries the whole persona, but for a field the request never
130	 *   mentioned that value is a **stale read, not an answer**.
131	 * - *Only where the draft still holds what was sent.* A save takes a moment,
132	 *   and somebody typing during that moment has written something the server
133	 *   has never seen. Its reply cannot speak for text it never saw.
134	 *
135	 * What is left is the case adoption exists for: a field this request sent,
136	 * untouched since, which egma stored in a form of its own — such as trimmed
137	 * text — and which the author should be looking at rather than their own
138	 * draft of it.
139	 */
140	function adopted(
141	  current: Draft | null,
142	  submitted: Submitted | undefined,
143	  fromServer: Persona,
144	): Draft | null {
145	  if (current === null) return current;
146	  // A write that carried none of these fields has nothing to adopt, because it
147	  // asked about none of them.
148	  if (submitted === undefined || submitted.personaId !== current.personaId) {
149	    return current;
150	  }
151	
152	  /** Sent, and untouched since. The only fields an answer may land on. */
153	  const answered = <T,>(mine: T, sent: T | undefined, theirs: T): T =>
154	    sent !== undefined && mine === sent ? theirs : mine;
155	
156	  const theirs = draftOf(fromServer.traits);
157	  const traits = { ...current.traits };
158	  if (submitted.traits !== undefined) {
159	    for (const trait of Object.keys(current.traits) as (keyof TraitsDraft)[]) {
160	      traits[trait] = answered(
161	        current.traits[trait],
162	        submitted.traits[trait],
163	        theirs[trait],
164	      );
165	    }
166	  }
167	
168	  const theirModels = modelsDraftOf(fromServer.models);
169	  const models = { ...current.models };
170	  if (submitted.models !== undefined) {
171	    for (const field of Object.keys(current.models) as (keyof ModelsDraft)[]) {
172	      models[field] = answered(
173	        current.models[field],
174	        submitted.models[field],
175	        theirModels[field],
176	      );
177	    }
178	  }
179	
180	  return {
181	    personaId: current.personaId,
182	    name: answered(current.name, submitted.name, fromServer.name),
183	    description: answered(
184	      current.description,
185	      submitted.description,
186	      fromServer.description ?? "",
187	    ),
188	    traits,
189	    models,
190	  };
191	}
192	
193	/**
194	 * Who they are, in the order and the grouping the boards read them back in.
195	 *
196	 * An optional trait nobody wrote is left out rather than shown empty: a label
197	 * over nothing is a fact about the form, not about the person.
198	 */
199	function traitReads(traits: PersonaTraits): readonly Read[] {
200	  const pair = (label: string, value: string | undefined): readonly Read[] =>
201	    value === undefined || value.trim() === "" ? [] : [{ label, value }];
202	
203	  return [
204	    { label: "Personality", value: traits.personality, wide: true },
205	    { label: "Language", value: traits.language, wide: true },
206	    ...pair("Manner", traits.manner),
207	    ...pair("Patience", traits.patience),
208	    ...pair("Accent", traits.accent),
209	    ...pair("Background noise", traits.backgroundNoise),
210	    ...pair("Under friction", traits.underFriction).map((one) => ({
211	      ...one,
212	      wide: true,
213	    })),
214	  ];
215	}
216	
217	/** What the simulator brings that person to life with. */
218	function modelReads(
219	  models: PersonaModels,
220	  form: PersonaForm | null,
221	): readonly Read[] {
222	  return [
223	    {
224	      label: "Language model",
225	      value: modelSaid(form?.modelCatalog, "llm", models.llm),
226	    },
227	    {
228	      label: "Speech-to-text model",
229	      value: modelSaid(form?.modelCatalog, "stt", models.stt),
230	    },
231	    {
232	      label: "Text-to-speech model",
233	      value: modelSaid(form?.modelCatalog, "tts", models.tts),
234	    },
235	    { label: "Speech rate", value: `${String(models.tts.speed)}×`, mono: true },
236	    { label: "Voice", value: models.tts.voiceId, mono: true, wide: true },
237	  ];
238	}
