  1	import type {
  2	  GetPersonaFormResponse,
  3	  GetPersonaResponse,
  4	  GetPersonaUsageResponse,
  5	  ListPersonasResponse,
  6	  ListPersonaVersionsResponse,
  7	} from "@egma/platform-api/client";
  8	
  9	/**
 10	 * The personas of one project, as `/v1/personas` answers them.
 11	 *
 12	 * A **persona** is the synthetic person who speaks with the agent. Egma
 13	 * supplies an Egma-provided persona to every project, and a project can author
 14	 * a Custom persona or fork the shared one. Human traits say how the person
 15	 * behaves; models say how the simulator brings that person to life.
 16	 *
 17	 * **Nothing in a persona says what that persona wants.** That is the test's
 18	 * scenario. The whole worth of a persona is that one of them is used in forty
 19	 * different situations, and a trait that said "asks to reschedule" would turn
 20	 * a reusable person into a second copy of one test. The editor says so where
 21	 * somebody is typing, and this file says so where somebody is reading.
 22	 *
 23	 * The shape is the API's own, field names included. Renaming its fields on the
 24	 * way in would put a second vocabulary between the contract and the page, and
 25	 * the two would drift the first time the API grew a field.
 26	 */
 27	
 28	export type Persona = GetPersonaResponse;
 29	export type PersonaTraits = Persona["traits"];
 30	
 31	export type PersonaModels = Persona["models"];
 32	export type ModelSelection = PersonaModels["llm"];
 33	export type PersonaPage = ListPersonasResponse;
 34	
 35	/** One frozen version, as history and the older-version read show it. */
 36	export type PersonaVersionPage = ListPersonaVersionsResponse;
 37	export type PersonaVersion = PersonaVersionPage["versions"][number];
 38	
 39	/**
 40	 * The active tests that name this persona, as `/v1/personas/{id}/usage`
 41	 * answers them.
 42	 *
 43	 * **It is read once, when a sheet or the archive confirmation opens, and never
 44	 * per row.** A list of forty personas would be forty more requests for a
 45	 * column nobody reads down; the two places it genuinely decides something are
 46	 * the sheet's `USED BY` and the archive confirmation, which has to say which
 47	 * tests would be left naming somebody who is no longer in the list.
 48	 */
 49	export type PersonaUsage = GetPersonaUsageResponse;
 50	
 51	export type PersonaForm = GetPersonaFormResponse;
 52	export type PersonaModelCatalogEntry = PersonaForm["modelCatalog"][number];
 53	
 54	/** The model choices and defaults exported by the server's adapter catalog. */
 55	/**
 56	 * The versioned field an editor is holding, before anybody decides whether it
 57	 * differs from what is stored.
 58	 */
 59	export type TraitsDraft = {
 60	  readonly personality: string;
 61	  readonly language: string;
 62	  readonly manner: string;
 63	  readonly patience: string;
 64	  readonly accent: string;
 65	  readonly backgroundNoise: string;
 66	  readonly underFriction: string;
 67	};
 68	
 69	/** What a persona egma has not been told anything about starts as. */
 70	export const BLANK_TRAITS: TraitsDraft = {
 71	  personality: "",
 72	  language: "en-US",
 73	  manner: "",
 74	  patience: "",
 75	  accent: "",
 76	  backgroundNoise: "",
 77	  underFriction: "",
 78	};
 79	
 80	/** The stored traits, as the editor holds them. */
 81	export function draftOf(traits: PersonaTraits): TraitsDraft {
 82	  return {
 83	    personality: traits.personality,
 84	    language: traits.language,
 85	    manner: traits.manner ?? "",
 86	    patience: traits.patience ?? "",
 87	    accent: traits.accent ?? "",
 88	    backgroundNoise: traits.backgroundNoise ?? "",
 89	    underFriction: traits.underFriction ?? "",
 90	  };
 91	}
 92	
 93	/** The human-traits draft, in the exact shape the API accepts. */
 94	export function traitsFrom(draft: TraitsDraft): PersonaTraits {
 95	  return { ...draft };
 96	}
 97	
 98	export function sameTraitsDraft(
 99	  left: TraitsDraft,
100	  right: TraitsDraft,
101	): boolean {
102	  return (Object.keys(left) as (keyof TraitsDraft)[]).every(
103	    (key) => left[key] === right[key],
104	  );
105	}
106	
107	/** Human traits in the order a read-only persona view shows them. */
108	export function describedTraits(
109	  traits: PersonaTraits,
110	): readonly { readonly label: string; readonly value: string }[] {
111	  const required = [
112	    { label: "Personality", value: traits.personality },
113	    { label: "Language", value: traits.language },
114	  ];
115	  const optional: readonly {
116	    readonly label: string;
117	    readonly value: string | undefined;
118	  }[] = [
119	    { label: "Manner", value: traits.manner },
120	    { label: "Patience", value: traits.patience },
121	    { label: "Accent", value: traits.accent },
122	    { label: "Background noise", value: traits.backgroundNoise },
123	    { label: "Under friction", value: traits.underFriction },
124	  ];
125	  return [
126	    ...required,
127	    ...optional.flatMap((one) =>
128	      one.value === undefined || one.value.trim() === ""
129	        ? []
130	        : [{ label: one.label, value: one.value }],
131	    ),
132	  ];
133	}
134	
135	/** What the model editor holds while a speed can still be half typed. */
136	export type ModelsDraft = {
137	  readonly llmProvider: string;
138	  readonly llmModel: string;
139	  readonly sttProvider: string;
140	  readonly sttModel: string;
141	  readonly ttsProvider: string;
142	  readonly ttsModel: string;
143	  readonly voiceId: string;
144	  readonly speed: string;
145	};
146	
147	export function modelsDraftOf(models: PersonaModels): ModelsDraft {
148	  return {
149	    llmProvider: models.llm.provider,
150	    llmModel: models.llm.model,
151	    sttProvider: models.stt.provider,
152	    sttModel: models.stt.model,
153	    ttsProvider: models.tts.provider,
154	    ttsModel: models.tts.model,
155	    voiceId: models.tts.voiceId,
156	    speed: String(models.tts.speed),
157	  };
158	}
159	
160	/** One complete models value, in the exact shape the API validates. */
161	export function modelsFrom(draft: ModelsDraft): PersonaModels {
162	  const speed = Number(draft.speed);
163	  const models = {
164	    llm: { provider: draft.llmProvider, model: draft.llmModel },
165	    stt: { provider: draft.sttProvider, model: draft.sttModel },
166	    tts: {
167	      provider: draft.ttsProvider,
168	      model: draft.ttsModel,
169	      voiceId: draft.voiceId,
170	      // Preserve invalid text so the server can give the one authoritative
171	      // range refusal. JSON cannot carry NaN.
172	      speed: Number.isNaN(speed) ? draft.speed : speed,
173	    },
174	  };
175	
176	  // The current API accepts invalid speed text so it can return its own range
177	  // refusal. The generated contract says this value is always a number. Keep
178	  // the existing request behavior until that contract mismatch is resolved.
179	  return models as unknown as PersonaModels;
180	}
181	
182	export function sameModelsDraft(
183	  left: ModelsDraft,
184	  right: ModelsDraft,
185	): boolean {
186	  return (Object.keys(left) as (keyof ModelsDraft)[]).every(
187	    (key) => left[key] === right[key],
188	  );
189	}
190	
191	/**
192	 * What a person calls a provider, as against what a persona stores.
193	 *
194	 * A persona stores `openai`; the server's catalog is where `OpenAI` is
195	 * written, and the boards read the sheet's models back with the catalog's own
196	 * label. The provider is the fallback rather than an error: the catalog is a
197	 * second read that may not have answered yet, and a persona can name a
198	 * provider the deployment has since stopped offering. Neither is a reason to
199	 * show nothing.
200	 */
201	export function modelSaid(
202	  catalog: readonly PersonaModelCatalogEntry[] | undefined,
203	  job: PersonaModelCatalogEntry["job"],
204	  selection: { readonly provider: string; readonly model: string },
205	): string {
206	  const entry = catalog?.find(
207	    (one) =>
208	      one.job === job &&
209	      one.provider === selection.provider &&
210	      one.model === selection.model,
211	  );
