   118	/**
   119	 * The card at this turn of the deck, whichever turn it is.
   120	 *
     1	import { parseArgs } from "node:util";
     2	
     3	import { newId } from "@egma/ids";
     4	import { eq } from "drizzle-orm";
     5	
     6	import { connect, disconnect, db } from "../client.ts";
     7	import {
     8	  archivePersona,
     9	  createPersona,
    10	  editPersona,
    11	  forkPersona,
    12	  getPersona,
    13	  getPersonaVersion,
    14	  listPersonas,
    15	  restorePersona,
    16	} from "../access/personas.ts";
    17	import { seedPersonaLibrary } from "../persona-library/seed.ts";
    18	import type { AuthContext } from "../access/context.ts";
    19	import { projectsOf } from "../access/projects.ts";
    20	import { reconcileGraderCatalog } from "../access/grader-library.ts";
    21	import { provisionOrganization } from "../access/provisioning.ts";
    22	import { runMigrations } from "../migrate.ts";
    23	import { organization, user } from "../schema/index.ts";
    24	
    25	/**
    26	 * Drives the persona factory from a terminal, until the real front door
    27	 * (the API) exists. Signup does not reach a terminal yet either, so the script
    28	 * keeps one development organization of its own — provisioned through the same
    29	 * front door signup will use — and acts in it as its admin.
    30	 *
    31	 *   node packages/db/dist/scripts/persona.js create \
    32	 *     --name "Impatient Rita" \
    33	 *     --personality "70, hard of hearing, gets louder when mishears."
    34	 *
    35	 *   node packages/db/dist/scripts/persona.js get prs_…
    36	 *   node packages/db/dist/scripts/persona.js list [--limit 50] [--cursor prs_…]
    37	 *   node packages/db/dist/scripts/persona.js fork prs_…
    38	 *   node packages/db/dist/scripts/persona.js archive prs_… [--replacement prs_…]
    39	 *   node packages/db/dist/scripts/persona.js restore prs_…
    40	 */
    41	
    42	const DATABASE_URL =
    43	  process.env.DATABASE_URL ?? "REDACTED";
    44	
    45	const DEV_SLUG = "factory-dev";
    46	const DEV_EMAIL = "factory@dev.local";
    47	
    48	async function actAsDevelopmentTenant(): Promise<AuthContext> {
    49	  await db()
    50	    .insert(user)
    51	    .values({ id: newId("usr"), email: DEV_EMAIL })
    52	    .onConflictDoNothing({ target: user.email });
    53	  const [developer] = await db()
    54	    .select({ id: user.id })
    55	    .from(user)
    56	    .where(eq(user.email, DEV_EMAIL));
    57	  if (developer === undefined) throw new Error("the development user vanished");
    58	
    59	  const existing = await db()
    60	    .select({ id: organization.id })
    61	    .from(organization)
    62	    .where(eq(organization.slug, DEV_SLUG));
    63	
    64	  const provisioned =
    65	    existing.length > 0
    66	      ? undefined
    67	      : await provisionOrganization({
    68	          ownerUserId: developer.id,
    69	          organizationName: "Factory dev",
    70	          organizationSlug: DEV_SLUG,
    71	          projectName: "Default",
    72	          projectSlug: "default",
    73	        });
    74	
    75	  const organizationId = existing[0]?.id ?? provisioned?.organizationId;
    76	  if (organizationId === undefined) throw new Error("no development organization");
    77	
    78	  const [firstProject] = await projectsOf(organizationId);
    79	  if (firstProject === undefined) throw new Error("no development project");
    80	
    81	  return {
    82	    userId: developer.id,
    83	    organizationId,
    84	    projectId: firstProject.id,
    85	    role: "admin",
    86	    via: "session",
    87	  };
    88	}
    89	
    90	function usage(): never {
    91	  console.error(
    92	    [
    93	      "usage:",
    94	      "  persona.js create --name <name> --personality <text> --language <tag>",
    95	      "    [--description <text>]",
    96	      "  persona.js get <prs_id>",
    97	      "  persona.js edit <prs_id> [--name <name>] [--description <text>]",
    98	      "    [--personality <text>] [--language <tag>]",
    99	      "  persona.js get-version <prsv_id>",
   100	      "  persona.js list [--limit <n>] [--cursor <prs_id>]",
   101	      "  persona.js fork <prs_id>",
   102	      "  persona.js archive <prs_id> [--replacement <prs_id>]",
   103	      "  persona.js restore <prs_id>",
   104	    ].join("\n"),
   105	  );
   106	  process.exit(1);
   107	}
   108	
   109	/** The one positional argument most commands take. */
   110	function requiredId(rest: readonly string[]): string {
   111	  const [id] = rest;
   112	  if (id === undefined) usage();
   113	  return id;
   114	}
   115	
   116	/** Print what the factory answered, or say the id reached nothing and exit. */
   117	function printPersona(id: string, found: unknown): void {
   118	  if (found === undefined) {
   119	    console.error(`no persona ${id} in the development project`);
   120	    process.exit(1);
   121	  }
   122	  console.log(JSON.stringify(found, null, 2));
   123	}
   124	
   125	async function main(): Promise<void> {
   126	  const [command, ...rest] = process.argv.slice(2);
   127	
   128	  await runMigrations(DATABASE_URL);
   129	  connect({ databaseUrl: DATABASE_URL, maxConnections: 2 });
   130	  await seedPersonaLibrary();
   131	  // egma's own graders, on the shelf before a project can be created — every
   132	  // project is born holding a copy of one, and the pointer is a foreign key.
   133	  await reconcileGraderCatalog();
   134	
   135	  const auth = await actAsDevelopmentTenant();
   136	
   137	  if (command === "create") {
   138	    const { values } = parseArgs({
   139	      args: rest,
   140	      options: {
   141	        name: { type: "string" },
   142	        description: { type: "string" },
   143	        personality: { type: "string" },
   144	        language: { type: "string" },
   145	      },
   146	    });
   147	    if (
   148	      values.name === undefined ||
   149	      values.personality === undefined ||
   150	      values.language === undefined
   151	    ) {
   152	      usage();
   153	    }
   154	
   155	    const created = await createPersona(auth, {
   156	      name: values.name,
   157	      description: values.description,
   158	      traits: {
   159	        personality: values.personality,
   160	        language: values.language,
   161	      },
   162	    });
   163	    console.log(JSON.stringify(created, null, 2));
   164	  } else if (command === "get") {
   165	    const id = requiredId(rest);
   166	    printPersona(id, await getPersona(auth, id));
   167	  } else if (command === "edit") {
   168	    const [id, ...flags] = rest;
   169	    if (id === undefined) usage();
   170	    const { values } = parseArgs({
   171	      args: flags,
   172	      options: {
   173	        name: { type: "string" },
   174	        description: { type: "string" },
   175	        personality: { type: "string" },
   176	        language: { type: "string" },
   177	      },
   178	    });
   179	
   180	    const current = await getPersona(auth, id);
   181	    if (current === undefined) {
   182	      printPersona(id, current);
   183	      return;
   184	    }
   185	    const traitsChanged =
   186	      values.personality !== undefined || values.language !== undefined;
   187	
   188	    const edited = await editPersona(auth, id, {
   189	      ...(values.name === undefined ? {} : { name: values.name }),
   190	      ...(values.description === undefined
   191	        ? {}
   192	        : { description: values.description }),
   193	      ...(traitsChanged
   194	        ? {
   195	            traits: {
   196	              ...current.traits,
   197	              ...(values.personality === undefined
   198	                ? {}
   199	                : { personality: values.personality }),
   200	              ...(values.language === undefined
   201	                ? {}
   202	                : { language: values.language }),
   203	            },
   204	          }
   205	        : {}),
   206	    });
   207	    printPersona(id, edited);
   208	  } else if (command === "get-version") {
   209	    const versionId = requiredId(rest);
   210	    const found = await getPersonaVersion(auth, versionId);
   211	    if (found === undefined) {
   212	      console.error(`no version ${versionId} in the development project`);
   213	      process.exit(1);
   214	    }
   215	    console.log(JSON.stringify(found, null, 2));
   216	  } else if (command === "list") {
   217	    const { values } = parseArgs({
   218	      args: rest,
   219	      options: {
   220	        limit: { type: "string" },
   221	        cursor: { type: "string" },
   222	      },
   223	    });
   224	    const page = await listPersonas(auth, {
   225	      limit: values.limit === undefined ? undefined : Number(values.limit),
   226	      cursor: values.cursor,
   227	    });
   228	    console.log(JSON.stringify(page, null, 2));
   229	  } else if (command === "fork") {
   230	    const id = requiredId(rest);
   231	    printPersona(id, await forkPersona(auth, id));
   232	  } else if (command === "archive") {
   233	    const [id, ...flags] = rest;
   234	    if (id === undefined) usage();
   235	    const { values } = parseArgs({
   236	      args: flags,
   237	      options: { replacement: { type: "string" } },
   238	    });
   239	    printPersona(
   240	      id,
   241	      await archivePersona(auth, id, {
   242	        ...(values.replacement === undefined
   243	          ? {}
   244	          : { replacementPersonaId: values.replacement }),
   245	      }),
   246	    );
   247	  } else if (command === "restore") {
   248	    const id = requiredId(rest);
   249	    printPersona(id, await restorePersona(auth, id));
   250	  } else {
   251	    usage();
   252	  }
   253	}
   254	
   255	try {
   256	  await main();
   257	} finally {
   258	  await disconnect();
   259	}
