     1	/**
     2	 * The words egma uses, taught while a coding agent writes the first tests.
     3	 *
     4	 * Writing a suite takes a couple of minutes. In that time a developer either
     5	 * learns what egma is talking about or does not, and every screen after this one
     6	 * assumes they did: the gate says "suite", the exit line says "tests", the
     7	 * results show grade scores and grading progress. So the
     8	 * wait teaches the vocabulary, one card at a time, beside the files as they
     9	 * land.
    10	 *
    11	 * The deck is plain data and it is read by the screen alone. Nothing in the
    12	 * walk waits on it, reads it, or is delayed by it — a developer on a fast
    13	 * machine sees one card and a developer on a slow one sees six, and the tests
    14	 * that get written are the same either way.
    15	 *
    16	 * The words are the glossary's own, deliberately. A card that taught a near
    17	 * synonym would be teaching a developer to say something egma does not answer
    18	 * to, which is worse than teaching nothing. So the deck is held to the same ban
    19	 * list as the text egma puts in front of a coding agent, and to no weaker one:
    20	 * a word egma will not say to a model is a word it will not put on a screen.
    21	 *
    22	 * The shape — a card beside a wait, turning on its own — is the PostHog
    23	 * wizard's idea. None of its code is here and none of these words are theirs.
    24	 */
    25	
    26	/** One card: a short heading and lines already broken to the pane's width. */
    27	export type LearnCard = {
    28	  readonly heading: string;
    29	  readonly lines: readonly string[];
    30	};
    31	
    32	/** How wide a card's lines are written to be, so the pane never rewraps them. */
    33	export const CARD_WIDTH = 32;
    34	
    35	/**
    36	 * The deck, in the order a developer meets the ideas: what they are authoring,
    37	 * who is on the other end of it, what happens when it runs, and what comes back.
    38	 */
    39	export const LEARN_CARDS: readonly LearnCard[] = [
    40	  {
    41	    heading: "A test",
    42	    lines: [
    43	      "One situation to put your agent",
    44	      "in: what the person on the other",
    45	      "end wants, and the expected",
    46	      "behaviors that say what should",
    47	      "happen.",
    48	      "",
    49	      "At least one behavior, always —",
    50	      "a test that cannot fail is not",
    51	      "a test.",
    52	    ],
    53	  },
    54	  {
    55	    heading: "A persona",
    56	    lines: [
    57	      "The synthetic person on the",
    58	      "other end: their manner, their",
    59	      "patience, how they behave when",
    60	      "things go wrong.",
    61	      "",
    62	      "A test names the personas it",
    63	      "should be run with. Naming none",
