    57	  if (developer === undefined) throw new Error("the development user vanished");
    58	
    59	  const existing = await db()
    60	    .select({ id: organization.id })
    61	    .from(organization)
    62	    .where(eq(organization.slug, DEV_SLUG));
    63	
    64	  const provisioned =
    65	    existing.length > 0
    66	      ? undefined
    67	      : await provisionOrganization({
    68	          ownerUserId: developer.id,
    69	          organizationName: "Factory dev",
    70	          organizationSlug: DEV_SLUG,
    71	          projectName: "Default",
    72	          projectSlug: "default",
    73	        });
    74	
    75	  const organizationId = existing[0]?.id ?? provisioned?.organizationId;
